-- Research and Travel now search the web. Personalities made from them still
-- say they can't look things up; swap that line where it's unchanged.
UPDATE "personalities" SET "instructions" = replace("instructions", '- What you know stops at your training. Say so when something may have changed since.', '- Search for anything that may have changed since your training, and open the primary sources rather than summaries of them.'), "revision" = "revision" + 1 WHERE "template_key" = 'research' AND "tools" @> '["web"]'::jsonb AND position('- What you know stops at your training. Say so when something may have changed since.' in "instructions") > 0;
--> statement-breakpoint
UPDATE "personalities" SET "instructions" = replace("instructions", '- Give rough costs as ranges and say they''re estimates. You can''t check live prices, opening hours, or availability, so tell them to confirm before booking.', '- Look up prices, opening hours, and entry rules when they matter, and give costs as ranges. Prices and availability change, so tell them to confirm before booking.'), "revision" = "revision" + 1 WHERE "template_key" = 'travel' AND "tools" @> '["web"]'::jsonb AND position('You can''t check live prices, opening hours, or availability' in "instructions") > 0;
